-- 015_fix_timetable_slot_day_period_decode.sql
-- Corrects timetable_slots: the original import (013) assumed period-major slot numbering,
-- which was wrong (it let ordinary lessons land in Registration/Evening Prep rows).
-- The real Nova-T convention is day-major: slot = (day-1)*9 + period.
-- Verified against Prep groups, which should land on Evening Prep every weekday.

DELETE FROM timetable_slots WHERE class_id IN (SELECT class_id FROM classes WHERE class_code IS NOT NULL);
